package br.com.onda;
import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import org.json.*;import java.io.*;import java.util.*;
/** Immutable selection. Only its token crosses Android's Binder boundary. */
@androidx.media3.common.util.UnstableApi
final class ChapterBatchPlan {
 static final class Row{final int index;final long start,end;final String title;Row(int index,long start,long end,String title){this.index=index;this.start=start;this.end=end;this.title=title;}}
 final String token,stamp,title;final Uri source,tree;final long duration,total;final int bitrate;final List<Row> rows;
 ChapterBatchPlan(String token,Uri source,Uri tree,String stamp,String title,long duration,int bitrate,List<Row> rows){this.token=token;this.source=source;this.tree=tree;this.stamp=stamp;this.title=title==null?"Coletânea":title;this.duration=duration;this.bitrate=bitrate;this.rows=Collections.unmodifiableList(new ArrayList<>(rows));long sum=0;for(Row row:rows)sum=Math.addExact(sum,row.end-row.start);total=sum;}
 static ChapterBatchPlan selected(Uri source,Uri tree,String stamp,String title,AudioChapterStore.Data data,boolean[] chosen,int bitrate)throws IOException{if(chosen.length!=data.chapters.size())throw new IOException("A seleção mudou. Abra as faixas novamente.");ArrayList<Row> rows=new ArrayList<>();for(int i=0;i<chosen.length;i++)if(chosen[i])rows.add(new Row(i,data.chapters.get(i).start,i+1<data.chapters.size()?data.chapters.get(i+1).start:data.duration,AudioChapterStore.label(data,i)));ChapterBatchPlan plan=new ChapterBatchPlan(UUID.randomUUID().toString(),source,tree,stamp,title,data.duration,bitrate,rows);plan.validate();return plan;}
 void validate()throws IOException{if(token==null||!token.matches("[a-f0-9-]{36}")||source==null||!("file".equals(source.getScheme())||"content".equals(source.getScheme()))||tree==null||!"content".equals(tree.getScheme())||!DocumentsContract.isTreeUri(tree)||stamp==null||duration<=0||rows.isEmpty()||!Mp3Quality.valid(bitrate))throw new IOException("Seleção inválida");int previous=-1;long previousEnd=-1;for(Row row:rows){if(row.index<=previous||row.start<0||row.end<=row.start||row.end>duration||row.start<previousEnd||row.title==null||row.title.length()>120)throw new IOException("Limites das faixas inválidos");previous=row.index;previousEnd=row.end;}}
 void validateSource(Context c)throws IOException{if(!stamp.equals(AudioChapterStore.stamp(c,source)))throw new IOException("O arquivo original mudou. Abra as faixas novamente.");AudioChapterStore.Data data=AudioChapterStore.load(c,source,stamp,duration);if(data==null)throw new IOException("As divisões mudaram. Abra as faixas novamente.");for(Row row:rows)if(row.index>=data.chapters.size()||data.chapters.get(row.index).start!=row.start||(row.index+1<data.chapters.size()?data.chapters.get(row.index+1).start:data.duration)!=row.end)throw new IOException("As divisões mudaram. Abra as faixas novamente.");}
 ChapterExportJob representative(){Row row=rows.get(0);return new ChapterExportJob(token,source,tree,stamp,title,row.start,row.end,duration,bitrate);}
 ChapterExportJob item(Row row,Uri target){return new ChapterExportJob(token,source,target,stamp,row.title,row.start,row.end,duration,bitrate);}
 String filename(Row row){return String.format(Locale.ROOT,"%03d - ",row.index+1)+DownloadLinks.filename(row.title)+".mp3";}
 JSONObject json()throws JSONException{JSONArray array=new JSONArray();for(Row row:rows)array.put(new JSONObject().put("index",row.index).put("start",row.start).put("end",row.end).put("title",row.title));return new JSONObject().put("token",token).put("source",source.toString()).put("tree",tree.toString()).put("stamp",stamp).put("title",title).put("duration",duration).put("bitrate",bitrate).put("rows",array);}
 static ChapterBatchPlan parse(String text)throws IOException{try{JSONObject j=new JSONObject(text);JSONArray array=j.getJSONArray("rows");List<Row> rows=new ArrayList<>();for(int i=0;i<array.length();i++){JSONObject row=array.getJSONObject(i);rows.add(new Row(row.getInt("index"),row.getLong("start"),row.getLong("end"),row.getString("title")));}ChapterBatchPlan plan=new ChapterBatchPlan(j.getString("token"),Uri.parse(j.getString("source")),Uri.parse(j.getString("tree")),j.getString("stamp"),j.getString("title"),j.getLong("duration"),j.getInt("bitrate"),rows);plan.validate();return plan;}catch(JSONException|ArithmeticException error){throw new IOException("Não foi possível ler a seleção",error);}}
 Intent screen(Context c){return new Intent(c,ChapterBatchExportActivity.class).putExtra("batch_token",token).putExtra("source",source.toString()).putExtra("stamp",stamp).putExtra("name",title).putExtra("duration",duration);}
}
